WITH SessionStats AS (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) AS event_type_values, SUM(CASE WHEN event_type = 'search' THEN duration_sec ELSE 0 END) AS search_duration_sec FROM web_events GROUP BY session_id) SELECT s.id, s.country, S.event_type_values, S.search_duration_sec FROM sessions s INNER JOIN SessionStats S ON s.id = S.session_id WHERE S.search_duration_sec >= 25
